	head, _, err := readRecord(cr)
	if errors.Is(err, io.EOF) {
		return nil, errInvalidHeader
	}
	if err != nil {
		return nil, csvFailure(err)
	}
	cols, ok := importColumnsOf(head)
	if !ok {
		return nil, errInvalidHeader
	}
	var recs []store.CustomerRecord
	for {
		fields, line, err := readRecord(cr)
		if errors.Is(err, io.EOF) {
			return recs, nil
		}
		if err != nil {
			return nil, csvFailure(err)
		}
		if len(recs) == maxImportRows {
			return nil, errTooManyRows
		}
		recs = append(recs, cols.record(line, fields))
	}
}

// readRecord returns the next record that is not blank, and the line where it starts.
func readRecord(cr *csv.Reader) ([]string, int, error) {
	for {
		fields, err := cr.Read()
		if err != nil {
			return nil, 0, err
		}
		if len(fields) == 1 && strings.TrimSpace(fields[0]) == "" {
			continue
		}
		line, _ := cr.FieldPos(0)
		return fields, line, nil
	}
}

// csvFailure is the error for a read that failed. A body over the size limit keeps its own error, so the caller can answer 413.
func csvFailure(err error) error {
	var tooBig *http.MaxBytesError
	if errors.As(err, &tooBig) {
		return err
	}
	return fmt.Errorf("%w: %v", errInvalidCSV, err)
}

// importColumns are the header columns an import reads, as indexes into a record. -1 means the header has no such column.
type importColumns struct {
	name, email, paymentMethod int
	metadata                   []metadataColumn
}

// metadataColumn is a "metadata.<key>" column and the metadata key it fills.
type metadataColumn struct {
	index int
	key   string
}

// importColumnsOf reads the header. Names match ignoring case and surrounding spaces, the first column of a name wins,
// and other columns are ignored. It reports false when there is no name or email column.
func importColumnsOf(head []string) (importColumns, bool) {
	cols := importColumns{name: -1, email: -1, paymentMethod: -1}
	for i, h := range head {
		h = strings.TrimSpace(h)
		switch lower := strings.ToLower(h); {
		case lower == "name" && cols.name < 0:
			cols.name = i
		case lower == "email" && cols.email < 0:
			cols.email = i
		case lower == "default_payment_method" && cols.paymentMethod < 0:
			cols.paymentMethod = i
		case len(h) > len("metadata.") && strings.EqualFold(h[:len("metadata.")], "metadata."):
			if key := strings.TrimSpace(h[len("metadata."):]); key != "" {
				cols.metadata = append(cols.metadata, metadataColumn{index: i, key: key})
			}
		}
	}
	return cols, cols.name >= 0 && cols.email >= 0
}

// record reads a data record. Empty metadata cells are not stored.
func (c importColumns) record(line int, fields []string) store.CustomerRecord {
	rec := store.CustomerRecord{
		Row:                  line,
		Name:                 cell(fields, c.name),
		Email:                cell(fields, c.email),
		DefaultPaymentMethod: cell(fields, c.paymentMethod),
	}
	for _, m := range c.metadata {
		if v := cell(fields, m.index); v != "" {
			if rec.Metadata == nil {
				rec.Metadata = map[string]string{}
			}
			rec.Metadata[m.key] = v
		}
	}
	return rec
}

// cell returns the trimmed value in column i, or "" when there is no such column.
func cell(fields []string, i int) string {
	if i < 0 || i >= len(fields) {
		return ""
	}
	return strings.TrimSpace(fields[i])
}

