// importCustomerCount is how many of the organization's customers the API lists.
func importCustomerCount(t *testing.T, e *apitest.Env, key string) int {
	t.Helper()
	var page struct {
		Items []store.Customer `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/customers?limit=100", key, nil, &page)
	return len(page.Items)
}

// importEventCount is how many customer.created events the organization has.
func importEventCount(t *testing.T, e *apitest.Env, key string) int {
	t.Helper()
	var page struct {
		Items []store.Event `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/events?type=customer.created&limit=100", key, nil, &page)
	return len(page.Items)
}

