46	// ImportCustomers checks the records in file order, as CreateCustomer does, and refuses an email that an existing customer
47	// or an earlier record has. When any record fails, it returns a RowError for each one and creates nothing. Otherwise, when
48	// dryRun is false, it creates every record in order. The checks and the creation happen under one lock, so the import
49	// is all or nothing.
50	func (s *Store) ImportCustomers(orgID string, recs []CustomerRecord, now time.Time, dryRun bool) ([]Customer, []RowError, error) {
51		s.mu.Lock()
52		defer s.mu.Unlock()
53		if _, ok := s.orgs[orgID]; !ok {
54			return nil, nil, ErrNotFound
55		}
56		norm := make([]CustomerRecord, len(recs))
57		var problems []RowError
58		seen := map[string]bool{}
59		for i, rec := range recs {
60			rec.Name, rec.Email = strings.TrimSpace(rec.Name), strings.TrimSpace(rec.Email)
61			rec.DefaultPaymentMethod = strings.TrimSpace(rec.DefaultPaymentMethod)
62			norm[i] = rec
63			key := normEmail(rec.Email)
64			code := ""
65			switch {
66			case rec.Name == "":
67				code = "missing_name"
68			case !validEmail(rec.Email):
69				code = "invalid_email"
70			case rec.DefaultPaymentMethod != "" && !strings.HasPrefix(rec.DefaultPaymentMethod, "pm_"):
71				code = "invalid_payment_method"
72			case s.customerEmailTaken(orgID, key):
73				code = "email_taken"
74			case seen[key]:
75				code = "duplicate_email"
76			}
77			seen[key] = true
78			if code != "" {
79				problems = append(problems, RowError{Row: rec.Row, Code: code})
80			}
81		}
