86		for _, rec := range norm {
87			c := Customer{ID: s.newID("cus"), OrgID: orgID, Name: rec.Name, Email: rec.Email,
88				DefaultPaymentMethod: rec.DefaultPaymentMethod, Metadata: rec.Metadata, CreatedAt: now.UTC()}
89			s.customers[c.ID] = c
90			s.customersByEmail[normEmail(c.Email)] = c.ID
91			out = append(out, copyCustomer(c))
92		}
93		return out, nil, nil
94	}
