158	// UpdateCustomer changes a customer with f, which may refuse with an error. The ID and organization cannot change.
159	func (s *Store) UpdateCustomer(orgID, id string, f func(*Customer) error) (Customer, error) {
160		s.mu.Lock()
161		defer s.mu.Unlock()
162		old, ok := s.customers[id]
163		if !ok || old.OrgID != orgID {
164			return Customer{}, ErrNotFound
165		}
166		c := copyCustomer(old)
167		if err := f(&c); err != nil {
168			return Customer{}, err
169		}
170		c.ID, c.OrgID, c.CreatedAt = old.ID, old.OrgID, old.CreatedAt
171		c.Name, c.Email = strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
172		if c.Name == "" || !validEmail(c.Email) {
173			return Customer{}, invalid("a customer needs a name and a valid email address")
174		}
175		if c.DefaultPaymentMethod != "" && !strings.HasPrefix(c.DefaultPaymentMethod, "pm_") {
176			return Customer{}, invalid("a payment method looks like pm_...")
177		}
178		if newKey := normEmail(c.Email); newKey != normEmail(old.Email) {
179			if other, ok := s.customersByEmail[newKey]; ok && s.customers[other].OrgID == orgID {
180				return Customer{}, ErrEmailTaken
181			}
182			delete(s.customersByEmail, normEmail(old.Email))
183			s.customersByEmail[newKey] = c.ID
184		}
185		s.customers[id] = c
186		return copyCustomer(c), nil
187	}
188	
189	// DeleteCustomer removes a customer.
190	func (s *Store) DeleteCustomer(orgID, id string) error {
191		s.mu.Lock()
192		defer s.mu.Unlock()
193		c, ok := s.customers[id]
194		if !ok || c.OrgID != orgID {
195			return ErrNotFound
196		}
197		delete(s.customers, id)
198		if s.customersByEmail[normEmail(c.Email)] == id {
199			delete(s.customersByEmail, normEmail(c.Email))
200		}
201		return nil
202	}
203	
204	func copyCustomer(c Customer) Customer {
205		if c.Metadata != nil {
206			m := make(map[string]string, len(c.Metadata))
207			for k, v := range c.Metadata {
208				m[k] = v
209			}
210			c.Metadata = m
211		}
212		return c
213	}
214	
215	func sortCustomers(cs []Customer) {
216		sort.Slice(cs, func(i, j int) bool {
217			if !cs[i].CreatedAt.Equal(cs[j].CreatedAt) {
218				return cs[i].CreatedAt.Before(cs[j].CreatedAt)
219			}
220			return cs[i].ID < cs[j].ID
221		})
222	}
