package api_test

import (
	"fmt"
	"net/http"
	"strings"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

// importCustomerCount is how many of the organization's customers the API lists.
func importCustomerCount(t *testing.T, e *apitest.Env, key string) int {
	t.Helper()
	var page struct {
		Items []store.Customer `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/customers?limit=100", key, nil, &page)
	return len(page.Items)
}

// importEventCount is how many customer.created events the organization has.
func importEventCount(t *testing.T, e *apitest.Env, key string) int {
	t.Helper()
	var page struct {
		Items []store.Event `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/events?type=customer.created&limit=100", key, nil, &page)
	return len(page.Items)
}

func TestImportCustomers(t *testing.T) {
	e := apitest.New(t)
	e.CreateCustomer(e.Acme, "Jane Doe", "jane@example.com")
	e.CreateCustomer(e.Globex, "Gus", "gus@example.com")
	events := importEventCount(t, e, e.Acme.Key)

	// A BOM, CRLF line ends, padded and reordered header names, ignored columns, a quoted field with a comma and quotes, a
	// quoted field with a line break, and a "metadata." column whose cell is empty.
	body := "\xef\xbb\xbf  Name ,Notes,Email,metadata.crm, METADATA.region ,default_payment_method\r\n" +
		"\"Doe, \"\"Ann\"\"\",n1,ann@example.com,7,EU,pm_123\r\n" +
		"\"Bob\nRoe\",n2,Bob@Example.com,,,\r\n" +
		"\n" +
		"Gus,n3,gus@example.com,,,\n"

	if r := e.Do("POST", "/v1/customers/import?dry_run=true", e.Acme.Key, body); r.Code != http.StatusOK {
		t.Fatalf("dry run: %s", r)
	} else if m := r.Map(t); m["created"] != float64(0) || m["would_create"] != float64(3) {
		t.Fatalf("dry run = %v", m)
	}
	if n := importCustomerCount(t, e, e.Acme.Key); n != 1 {
		t.Fatalf("dry run created customers: %d listed", n)
	}

	var got struct {
		Created int              `json:"created"`
		Items   []store.Customer `json:"items"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/customers/import", e.Acme.Key, body, &got)
	if got.Created != 3 || len(got.Items) != 3 {
		t.Fatalf("import = %+v", got)
	}
	ann, bob, gus := got.Items[0], got.Items[1], got.Items[2]
	if ann.Name != `Doe, "Ann"` || ann.Email != "ann@example.com" || ann.DefaultPaymentMethod != "pm_123" ||
		ann.Metadata["crm"] != "7" || ann.Metadata["region"] != "EU" || len(ann.Metadata) != 2 {
		t.Fatalf("ann = %+v", ann)
	}
	if bob.Name != "Bob\nRoe" || bob.Email != "Bob@Example.com" || bob.Metadata != nil || bob.DefaultPaymentMethod != "" {
		t.Fatalf("bob = %+v", bob)
	}
	if gus.Email != "gus@example.com" || gus.OrgID != e.Acme.ID {
		t.Fatalf("gus = %+v (another organization's customer must not block the import)", gus)
	}
	if n := importCustomerCount(t, e, e.Acme.Key); n != 4 {
		t.Fatalf("listed %d customers, want 4", n)
	}
	if n := importEventCount(t, e, e.Acme.Key); n != events+3 {
		t.Fatalf("customer.created events = %d, want %d", n, events+3)
	}

	// The same file again: every email is now taken.
	if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, body); r.Code != http.StatusUnprocessableEntity {
		t.Fatalf("second import: %s", r)
	}
}

func TestImportCustomersHeader(t *testing.T) {
	e := apitest.New(t)
	for _, body := range []string{
		"",
		"\n\r\n  \n",
		"name,phone\nJane,555\n",
		"email\njane@example.com\n",
	} {
		if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, body); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_header" {
			t.Fatalf("header %q: %s", body, r)
		}
	}
	// A header with no records is valid and creates none. A header may repeat a column: the first one is read.
	var got struct {
		Created int              `json:"created"`
		Items   []store.Customer `json:"items"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/customers/import", e.Acme.Key, "email,name,Name\n", &got)
	if got.Created != 0 || got.Items == nil || len(got.Items) != 0 {
		t.Fatalf("header only = %+v", got)
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/customers/import", e.Acme.Key, "Name,Email,Name\nJane,jane@example.com,Other\n", &got)
	if got.Created != 1 || got.Items[0].Name != "Jane" {
		t.Fatalf("repeated name column = %+v", got)
	}
}

func TestImportCustomersInvalidCSV(t *testing.T) {
	e := apitest.New(t)
	for _, body := range []string{
		"name,email\n\"Jane,jane@example.com\n",
		"name,email\nJane,jane@example.com,extra\n",
		"name,email\nJane\n",
	} {
		if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, body); r.Code != http.StatusBadRequest || r.Map(t)["error"] != "invalid_csv" {
			t.Fatalf("body %q: %s", body, r)
		}
	}
}

func TestImportCustomersTooManyRows(t *testing.T) {
	e := apitest.New(t)
	var b strings.Builder
	b.WriteString("name,email\n")
	for i := range 10000 {
		fmt.Fprintf(&b, "Person %d,person%d@example.com\n", i, i)
	}
	full := b.String()
	if r := e.Do("POST", "/v1/customers/import?dry_run=true", e.Acme.Key, full); r.Code != http.StatusOK || r.Map(t)["would_create"] != float64(10000) {
		t.Fatalf("10,000 records: %s", r)
	}
	if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, full+"Too Many,too-many@example.com\n"); r.Code != http.StatusRequestEntityTooLarge || r.Map(t)["error"] != "too_many_rows" {
		t.Fatalf("10,001 records: %s", r)
	}
	if n := importCustomerCount(t, e, e.Acme.Key); n != 0 {
		t.Fatalf("refused import created %d customers", n)
	}
}

func TestImportCustomersInvalidRows(t *testing.T) {
	e := apitest.New(t)
	e.CreateCustomer(e.Acme, "Jane Doe", "jane@example.com")
	// Line numbers: the header is line 1, and the record that starts on line 3 runs on to line 4.
	body := "name,email,default_payment_method\n" +
		",missing@example.com,\n" + // 2: no name
		"\"Multi\nLine\",bad-email,\n" + // 3: bad email
		"Pay,pay@example.com,card_123\n" + // 5: payment method
		"Taken,JANE@example.com,\n" + // 6: an existing customer has it
		"Dup,new@example.com,\n" + // 7: fine
		"Dup again,NEW@example.com,\n" + // 8: an earlier record has it
		",,\n" + // 9: no name, and no email either: the first failing check is reported
		"Ok,ok@example.com,\n" // 10: fine
	want := []map[string]any{
		{"row": float64(2), "error": "missing_name"},
		{"row": float64(3), "error": "invalid_email"},
		{"row": float64(5), "error": "invalid_payment_method"},
		{"row": float64(6), "error": "email_taken"},
		{"row": float64(8), "error": "duplicate_email"},
		{"row": float64(9), "error": "missing_name"},
	}
	for _, path := range []string{"/v1/customers/import", "/v1/customers/import?dry_run=true"} {
		r := e.Do("POST", path, e.Acme.Key, body)
		m := r.Map(t)
		if r.Code != http.StatusUnprocessableEntity || m["error"] != "invalid_rows" {
			t.Fatalf("%s: %s", path, r)
		}
		rows, _ := m["rows"].([]any)
		if len(rows) != len(want) {
			t.Fatalf("%s: rows = %v", path, m["rows"])
		}
		for i, row := range rows {
			if fmt.Sprint(row) != fmt.Sprint(want[i]) {
				t.Fatalf("%s: row %d = %v, want %v", path, i, row, want[i])
			}
		}
	}
	if n := importCustomerCount(t, e, e.Acme.Key); n != 1 {
		t.Fatalf("refused import created customers: %d listed", n)
	}
}
