		t.Fatalf("dry run created customers: %d listed", n)
	}

	var got struct {
		Created int              `json:"created"`
		Items   []store.Customer `json:"items"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/customers/import", e.Acme.Key, body, &got)
	if got.Created != 3 || len(got.Items) != 3 {
		t.Fatalf("import = %+v", got)
	}
	ann, bob, gus := got.Items[0], got.Items[1], got.Items[2]
	if ann.Name != `Doe, "Ann"` || ann.Email != "ann@example.com" || ann.DefaultPaymentMethod != "pm_123" ||
		ann.Metadata["crm"] != "7" || ann.Metadata["region"] != "EU" || len(ann.Metadata) != 2 {
		t.Fatalf("ann = %+v", ann)
	}
	if bob.Name != "Bob\nRoe" || bob.Email != "Bob@Example.com" || bob.Metadata != nil || bob.DefaultPaymentMethod != "" {
		t.Fatalf("bob = %+v", bob)
	}
	if gus.Email != "gus@example.com" || gus.OrgID != e.Acme.ID {
		t.Fatalf("gus = %+v (another organization's customer must not block the import)", gus)
	}
	if n := importCustomerCount(t, e, e.Acme.Key); n != 4 {
		t.Fatalf("listed %d customers, want 4", n)
	}
	if n := importEventCount(t, e, e.Acme.Key); n != events+3 {
		t.Fatalf("customer.created events = %d, want %d", n, events+3)
	}

	// The same file again: every email is now taken.
	if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, body); r.Code != http.StatusUnprocessableEntity {
		t.Fatalf("second import: %s", r)
	}
}

func TestImportCustomersHeader(t *testing.T) {
	e := apitest.New(t)
	for _, body := range []string{
		"",
		"\n\r\n  \n",
		"name,phone\nJane,555\n",
		"email\njane@example.com\n",
	} {
		if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, body); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_header" {
			t.Fatalf("header %q: %s", body, r)
		}
	}
	// A header with no records is valid and creates none. A header may repeat a column: the first one is read.
	var got struct {
		Created int              `json:"created"`
		Items   []store.Customer `json:"items"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/customers/import", e.Acme.Key, "email,name,Name\n", &got)
	if got.Created != 0 || got.Items == nil || len(got.Items) != 0 {
		t.Fatalf("header only = %+v", got)
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/customers/import", e.Acme.Key, "Name,Email,Name\nJane,jane@example.com,Other\n", &got)
	if got.Created != 1 || got.Items[0].Name != "Jane" {
		t.Fatalf("repeated name column = %+v", got)
	}
}

