func TestImportCustomersTooManyRows(t *testing.T) {
	e := apitest.New(t)
	var b strings.Builder
	b.WriteString("name,email\n")
	for i := range 10000 {
		fmt.Fprintf(&b, "Person %d,person%d@example.com\n", i, i)
	}
	full := b.String()
	if r := e.Do("POST", "/v1/customers/import?dry_run=true", e.Acme.Key, full); r.Code != http.StatusOK || r.Map(t)["would_create"] != float64(10000) {
		t.Fatalf("10,000 records: %s", r)
	}
	if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, full+"Too Many,too-many@example.com\n"); r.Code != http.StatusRequestEntityTooLarge || r.Map(t)["error"] != "too_many_rows" {
		t.Fatalf("10,001 records: %s", r)
	}
	if n := importCustomerCount(t, e, e.Acme.Key); n != 0 {
		t.Fatalf("refused import created %d customers", n)
	}
}

func TestImportCustomersInvalidRows(t *testing.T) {
	e := apitest.New(t)
	e.CreateCustomer(e.Acme, "Jane Doe", "jane@example.com")
	// Line numbers: the header is line 1, and the record that starts on line 3 runs on to line 4.
	body := "name,email,default_payment_method\n" +
		",missing@example.com,\n" + // 2: no name
		"\"Multi\nLine\",bad-email,\n" + // 3: bad email
		"Pay,pay@example.com,card_123\n" + // 5: payment method
		"Taken,JANE@example.com,\n" + // 6: an existing customer has it
		"Dup,new@example.com,\n" + // 7: fine
		"Dup again,NEW@example.com,\n" + // 8: an earlier record has it
		",,\n" + // 9: no name, and no email either: the first failing check is reported
		"Ok,ok@example.com,\n" // 10: fine
	want := []map[string]any{
		{"row": float64(2), "error": "missing_name"},
		{"row": float64(3), "error": "invalid_email"},
		{"row": float64(5), "error": "invalid_payment_method"},
		{"row": float64(6), "error": "email_taken"},
		{"row": float64(8), "error": "duplicate_email"},
		{"row": float64(9), "error": "missing_name"},
	}
	for _, path := range []string{"/v1/customers/import", "/v1/customers/import?dry_run=true"} {
		r := e.Do("POST", path, e.Acme.Key, body)
		m := r.Map(t)
		if r.Code != http.StatusUnprocessableEntity || m["error"] != "invalid_rows" {
			t.Fatalf("%s: %s", path, r)
		}
		rows, _ := m["rows"].([]any)
		if len(rows) != len(want) {
			t.Fatalf("%s: rows = %v", path, m["rows"])
		}
		for i, row := range rows {
			if fmt.Sprint(row) != fmt.Sprint(want[i]) {
				t.Fatalf("%s: row %d = %v, want %v", path, i, row, want[i])
			}
		}
	}
	if n := importCustomerCount(t, e, e.Acme.Key); n != 1 {
		t.Fatalf("refused import created customers: %d listed", n)
	}
}
